/** CITY-LIFE-TELLING — prompts generated by the live MATSim simulation.
 *
 *  The integration between the simulation and story collection is a LOOP,
 *  not a dashboard: the simulation's anomalies are turned into neutral
 *  invitations to tell ("what did you observe on this line in this time
 *  window?"), shown to citizens in the composer. The prompt asks for the
 *  FORM of the missing information, never for the content — no hypothesis,
 *  no suggested answer (protocol §7.3). Every story born from a prompt
 *  carries a `prompt_ref`, so researchers can compare prompted vs free
 *  stories (non-directivity control, protocol §7.2).
 *
 *  Deterministic: same snapshot ⇒ same prompts. */

import { inFocus, type FocusArea } from './matsim/calibration.js'
import { SEED_LINES } from './matsim/network.js'
import { STATUS_SEVERITY, type MatsimSnapshot, type ServiceStatus } from './matsim/types.js'

export interface SimulationPrompt {
  id: string
  lineId: string
  lineLabel: string
  simStatus: ServiceStatus
  simDelaySec: number
  load: number
  tick: number
  /** Anomaly score 0..100 used for ranking (exposed for research). */
  score: number
}

/** Up to `limit` anomaly prompts, most anomalous first. When a focus area
 *  is given, only lines crossing it are prompted — the same containment
 *  rule the calibrated agents obey. */
export function simulationPrompts(snapshot: MatsimSnapshot | null, limit = 3, focus?: FocusArea): SimulationPrompt[] {
  if (!snapshot) return []
  const scored = snapshot.lines
    .map((state) => {
      const line = SEED_LINES.find((l) => l.id === state.lineId)
      if (focus && !(line?.stops.some((stop) => inFocus(focus, stop.lat, stop.lon)) ?? false)) return null
      const score = STATUS_SEVERITY[state.status] * 100
        + Math.min(600, Math.max(0, state.avgDelaySec)) / 6
        + state.load * 20
      return {
        id: `clt-sim-${state.lineId}-${snapshot.tick}`,
        lineId: state.lineId,
        lineLabel: line?.label ?? state.lineId,
        simStatus: state.status,
        simDelaySec: state.avgDelaySec,
        load: state.load,
        tick: snapshot.tick,
        score: Math.round(score),
      }
    })
    .filter((p): p is SimulationPrompt => !!p && (p.simStatus !== 'nominal' || p.simDelaySec >= 120))
    .sort((a, b) => b.score - a.score || a.lineId.localeCompare(b.lineId))
  return scored.slice(0, limit)
}

/** Compact reference stored on a story born from a simulation prompt. */
export interface PromptRef {
  source: 'simulation'
  lineId: string
  tick: number
  simStatus: ServiceStatus
}

export function promptRefOf(prompt: SimulationPrompt): PromptRef {
  return { source: 'simulation', lineId: prompt.lineId, tick: prompt.tick, simStatus: prompt.simStatus }
}
